create table public.property_profiles(property_id uuid primary key references properties(id),slug text,description text,photos jsonb not null default '[]',published boolean not null default false,public_name text,suburb text,address_public text,amenities jsonb not null default '[]');
create table public.room_profiles(room_id uuid primary key references rooms(id),title text,description text,photos jsonb not null default '[]',amenities jsonb not null default '[]',offer_type text not null default 'private',ready boolean not null default false,published boolean not null default false,slug text);
create table public.reservations(id uuid primary key default gen_random_uuid(),reservation_code text unique not null,property_id uuid references properties(id),room_id uuid references rooms(id),full_name text not null,email text not null,phone text not null,arrival_date date not null,departure_date date,status text not null default 'pending',created_at timestamptz not null default now(),offer_type text,spaces_requested integer not null default 1,occupation_type text,introduction text not null default '',stay_type text,weekly_rate numeric(10,2),admin_notes text,confirmed_at timestamptz,cancelled_at timestamptz,updated_at timestamptz not null default now());
create table public.reservation_events(id bigint generated by default as identity primary key,reservation_id uuid not null references reservations(id),action text not null,actor text not null,details jsonb not null default '{}',created_at timestamptz not null default now());
create table public.room_blocks(id uuid primary key default gen_random_uuid(),room_id uuid not null references rooms(id),starts_on date not null,ends_on date not null,reason text not null,spaces integer not null default 1,created_at timestamptz not null default now());
create table public.contracts(id uuid primary key default gen_random_uuid(),reservation_id uuid not null references reservations(id),version integer not null default 1,status text not null default 'draft',fields jsonb not null default '{}',document_path text,approved_by text,approved_at timestamptz,created_at timestamptz not null default now(),unique(reservation_id,version));
create table public.notification_outbox(id uuid primary key default gen_random_uuid(),reservation_id uuid references reservations(id),recipient text not null,kind text not null,payload jsonb not null default '{}',status text not null default 'pending',attempts integer not null default 0,last_error text,created_at timestamptz not null default now(),sent_at timestamptz);
do $$declare t text;begin foreach t in array array['property_profiles','room_profiles','reservations','reservation_events','room_blocks','contracts','notification_outbox'] loop execute format('alter table %I enable row level security',t);execute format('create policy staff_only on %I for all to authenticated using(public.is_sakan_staff()) with check(public.is_sakan_staff())',t);end loop;end$$;
grant usage on schema public,auth to anon,authenticated,service_role;
grant all on all tables in schema public to authenticated,service_role;
grant usage,select on all sequences in schema public to authenticated,service_role;
